import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.BDCokyix.js";const k=JSON.parse('{"title":"cargo xtask","description":"","frontmatter":{},"headers":[],"relativePath":"development/xtask.md","filePath":"development/xtask.md","lastUpdated":1780254295000}'),o={name:"development/xtask.md"};function n(l,s,r,p,d,h){return e(),i("div",null,[...s[0]||(s[0]=[t('<h1 id="cargo-xtask" tabindex="-1"><code>cargo xtask</code> <a class="header-anchor" href="#cargo-xtask" aria-label="Permalink to &quot;`cargo xtask`&quot;">​</a></h1><p>This repo uses a small Rust CLI (<code>xtask/</code>) for automation that must be portable and CI-friendly.</p><p><code>cargo xtask</code> is part of the backend-owned toolchain. It is the right place for Rust workspace automation and Cargo-oriented CI helpers, not for desktop pnpm workflows or general repo scripting.</p><p><code>cargo xtask</code> is wired via <code>.cargo/config.toml</code>, so you can run it from the repo root without extra setup. You can also run it explicitly from <code>backend/</code>, which is the clearer ownership model as the repo moves toward less root-level coupling.</p><h2 id="common-commands" tabindex="-1">Common commands <a class="header-anchor" href="#common-commands" aria-label="Permalink to &quot;Common commands&quot;">​</a></h2><p>Show help:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xtask</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xtask</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Read versions used by CI:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xtask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Cargo.toml</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xtask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../Cargo.toml</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="ownership-boundaries" tabindex="-1">Ownership boundaries <a class="header-anchor" href="#ownership-boundaries" aria-label="Permalink to &quot;Ownership boundaries&quot;">​</a></h2><p>Use <code>cargo xtask</code> for tasks that are primarily about:</p><ul><li>Cargo workspace metadata and version resolution</li><li>backend CI preparation that should stay cross-platform and shell-light</li><li>structured machine-readable output consumed by GitHub Actions</li></ul><p>Do not move these concerns into <code>cargo xtask</code>:</p><ul><li><code>pnpm</code> install, lint, build, or release flows owned by <code>desktop/</code></li><li>Tauri desktop app development commands</li><li>ad hoc root-level glue that would hide which workspace actually owns the command</li></ul><h2 id="ci-integration" tabindex="-1">CI integration <a class="header-anchor" href="#ci-integration" aria-label="Permalink to &quot;CI integration&quot;">​</a></h2><p>GitHub Actions workflows use <code>cargo xtask</code> for Cargo workspace version resolution (e.g. resolving the workspace version label consumed by <code>release-server.yml</code>). The desktop and server release pipelines themselves live entirely in their own workflows (<code>release-desktop.yml</code>, <code>release-server.yml</code>) — <code>xtask</code> is not involved in bundling, packaging, or asset publication.</p><h2 id="extending-xtask" tabindex="-1">Extending xtask <a class="header-anchor" href="#extending-xtask" aria-label="Permalink to &quot;Extending xtask&quot;">​</a></h2><p>When adding a new subcommand:</p><ul><li>Keep inputs explicit (flags/env) and outputs stable (especially JSON consumed by CI).</li><li>Prefer cross-platform Rust filesystem/process APIs over shell logic.</li><li>Prefer backend-specific ownership. If a task mainly exists to operate <code>desktop/</code>, keep it in the desktop workspace instead.</li></ul>',19)])])}const m=a(o,[["render",n]]);export{k as __pageData,m as default};
